.pill-1{
  --p1-hair: color-mix(in srgb, var(--fg) 10%, transparent);
  --p1-ease: cubic-bezier(.2,.8,.2,1);
  box-sizing:border-box;position:relative;display:inline-flex;flex-direction:column;align-items:stretch;
  min-width:220px;max-width:260px;min-height:44px;border-radius:22px;overflow:hidden;
  color:var(--fg);
  background:color-mix(in srgb, var(--bg) 88%, transparent);
  -webkit-backdrop-filter:blur(24px) saturate(160%);backdrop-filter:blur(24px) saturate(160%);
  box-shadow:0 0 0 1px var(--p1-hair), 0 10px 28px var(--shadow), 0 1px 2px var(--shadow);
  font:500 13px/1.3 -apple-system,"SF Pro Text",system-ui,sans-serif;
  -webkit-font-smoothing:antialiased;
  transition:max-width .38s var(--p1-ease), border-radius .38s var(--p1-ease), opacity .2s ease, transform .38s var(--p1-ease);
  animation:pill-1-appear .32s var(--p1-ease) both;
}
.pill-1__body{display:flex;align-items:center;gap:10px;height:44px;padding:0 16px 0 12px}
.pill-1__svg{flex:none;display:block;overflow:visible}
.pill-1__ribbon,.pill-1__trail{fill:none;stroke-width:2.25;stroke-linecap:round;stroke-linejoin:round;
  transition:stroke .3s ease, opacity .3s ease}
.pill-1__ribbon{stroke:var(--fg)}
.pill-1__trail{stroke:var(--accent);stroke-width:2;opacity:.35}
.pill-1__label{display:flex;flex-direction:column;justify-content:center;min-width:0;line-height:1.25}
.pill-1__state{display:none;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:var(--fg)}
.pill-1__hint{display:none;font-size:11px;font-weight:400;color:var(--muted);white-space:nowrap}

/* state: appear */
.pill-1[data-state="appear"] .pill-1__s-appear{display:inline}
.pill-1[data-state="appear"] .pill-1__ribbon{stroke:var(--muted);stroke-dasharray:100;stroke-dashoffset:100;
  animation:pill-1-draw .5s var(--p1-ease) .1s forwards}
.pill-1[data-state="appear"] .pill-1__trail{opacity:0}

/* state: listening */
.pill-1[data-state="listening"] .pill-1__s-listening,
.pill-1[data-state="listening"] .pill-1__hint{display:inline}
.pill-1[data-state="listening"] .pill-1__ribbon{stroke:var(--fg)}

/* processing states share a dash sweep; direction/cadence encode the job */
.pill-1[data-state="transcribing"] .pill-1__s-transcribing,
.pill-1[data-state="transforming"] .pill-1__s-transforming,
.pill-1[data-state="searching"] .pill-1__s-searching{display:inline;color:var(--muted)}
.pill-1[data-state="transcribing"] .pill-1__ribbon,
.pill-1[data-state="transforming"] .pill-1__ribbon,
.pill-1[data-state="searching"] .pill-1__ribbon{stroke:var(--accent)}
.pill-1[data-state="transcribing"] .pill-1__ribbon{stroke-dasharray:14 10;animation:pill-1-sweep .9s linear infinite}
.pill-1[data-state="transforming"] .pill-1__ribbon{stroke-dasharray:5 6;animation:pill-1-sweep 1.1s linear infinite reverse}
.pill-1[data-state="searching"] .pill-1__ribbon{stroke-dasharray:2 5;animation:pill-1-sweep .6s linear infinite}
.pill-1[data-state="transcribing"] .pill-1__trail,
.pill-1[data-state="transforming"] .pill-1__trail,
.pill-1[data-state="searching"] .pill-1__trail{opacity:.18}

/* state: done -> ribbon tweens into a check, capsule opens into a card */
.pill-1[data-state="done"]{max-width:420px;border-radius:18px}
.pill-1[data-state="done"] .pill-1__s-done{display:inline;color:var(--ok)}
.pill-1[data-state="done"] .pill-1__ribbon{stroke:var(--ok);stroke-width:2.5;
  transition:d .45s var(--p1-ease), stroke .3s ease, stroke-width .3s ease}
.pill-1[data-state="done"] .pill-1__trail{opacity:0}
.pill-1__preview{display:none;padding:0 16px 12px 16px;border-top:1px solid var(--p1-hair)}
.pill-1[data-state="done"] .pill-1__preview,
.pill-1[data-state="failed"] .pill-1__preview{display:block;animation:pill-1-rise .3s var(--p1-ease) both}
.pill-1__text{padding-top:10px;font-weight:400;font-size:13px;line-height:1.4;color:var(--fg);
  display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere}
.pill-1__card{display:none;padding-top:10px}
.pill-1[data-kind="search"] .pill-1__card{display:block}
.pill-1[data-kind="search"] .pill-1__text{display:none}
.pill-1__card-title{font-weight:600;font-size:13px;color:var(--fg);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.pill-1__card-body{margin-top:3px;font-weight:400;font-size:12px;line-height:1.4;color:var(--muted);
  display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere}

/* state: failed -> flat line in --err, brief shake */
.pill-1[data-state="failed"]{max-width:360px;border-radius:18px;animation:pill-1-shake .4s var(--p1-ease)}
.pill-1[data-state="failed"] .pill-1__s-failed{display:inline;color:var(--err)}
.pill-1[data-state="failed"] .pill-1__ribbon{stroke:var(--err);transition:d .3s var(--p1-ease), stroke .2s ease}
.pill-1[data-state="failed"] .pill-1__trail{opacity:0}
.pill-1[data-state="failed"] .pill-1__text{color:var(--muted)}

/* state: hidden (cancel / dismiss) */
.pill-1[data-state="hidden"]{opacity:0;transform:translateY(8px) scale(.96);pointer-events:none}

@keyframes pill-1-appear{from{opacity:0;transform:translateY(10px) scale(.94)}to{opacity:1;transform:none}}
@keyframes pill-1-draw{to{stroke-dashoffset:0}}
@keyframes pill-1-sweep{from{stroke-dashoffset:0}to{stroke-dashoffset:-24}}
@keyframes pill-1-rise{from{opacity:0;transform:translateY(-4px)}to{opacity:1;transform:none}}
@keyframes pill-1-shake{0%,100%{transform:translateX(0)}25%{transform:translateX(-4px)}55%{transform:translateX(3px)}80%{transform:translateX(-1px)}}

@media (prefers-reduced-motion: reduce){
  .pill-1,.pill-1[data-state="failed"],.pill-1[data-state="appear"] .pill-1__ribbon,
  .pill-1[data-state="transcribing"] .pill-1__ribbon,.pill-1[data-state="transforming"] .pill-1__ribbon,
  .pill-1[data-state="searching"] .pill-1__ribbon,.pill-1__preview{animation:none}
  .pill-1[data-state="appear"] .pill-1__ribbon{stroke-dashoffset:0}
  .pill-1{transition:opacity .15s ease}
  .pill-1[data-state="done"] .pill-1__ribbon,.pill-1[data-state="failed"] .pill-1__ribbon{transition:stroke .2s ease}
  .pill-1[data-state="hidden"]{transform:none}
}

