(function(){
  var MID=14, N=7, X0=4, X1=92;
  var xs=[]; for(var i=0;i<N;i++) xs.push(X0+(X1-X0)*i/(N-1));
  var env=[0.15,0.6,0.95,1,0.95,0.6,0.15];
  var CHECK=[[36,14],[40.5,18.5],[45,23],[49,19],[53,15],[57,11],[61,7]];
  var phase=0, lv=0, lvTrail=0, lastState=null;
  var reduce=false; try{ reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches; }catch(e){}
  function f(v){ return Math.round(v*100)/100; }
  function smooth(pts){ // Catmull-Rom -> M + 6 C (constant structure, tweenable)
    var d='M'+f(pts[0][0])+' '+f(pts[0][1]);
    for(var i=0;i<pts.length-1;i++){
      var p0=pts[i-1]||pts[i], p1=pts[i], p2=pts[i+1], p3=pts[i+2]||p2;
      d+=' C'+f(p1[0]+(p2[0]-p0[0])/6)+' '+f(p1[1]+(p2[1]-p0[1])/6)+' '+f(p2[0]-(p3[0]-p1[0])/6)+' '+f(p2[1]-(p3[1]-p1[1])/6)+' '+f(p2[0])+' '+f(p2[1]);
    }
    return d;
  }
  function straight(pts){ // collinear controls -> crisp polyline, same M + 6 C structure
    var d='M'+f(pts[0][0])+' '+f(pts[0][1]);
    for(var i=0;i<pts.length-1;i++){
      var a=pts[i], b=pts[i+1], dx=b[0]-a[0], dy=b[1]-a[1];
      d+=' C'+f(a[0]+dx/3)+' '+f(a[1]+dy/3)+' '+f(a[0]+dx*2/3)+' '+f(a[1]+dy*2/3)+' '+f(b[0])+' '+f(b[1]);
    }
    return d;
  }
  function wave(amp, ph){
    var pts=[];
    for(var i=0;i<N;i++){
      var y=MID + (Math.sin(ph+i*1.05) + 0.25*Math.sin(ph*1.7+i*2.3)) * env[i] * amp;
      pts.push([xs[i], y]);
    }
    return smooth(pts);
  }
  function flat(){ var pts=[]; for(var i=0;i<N;i++) pts.push([xs[i],MID]); return straight(pts); }
  function setD(el,d){ if(el && el.getAttribute('d')!==d) el.setAttribute('d',d); }

  window.pill1_tick=function(level, state){
    var root=document.querySelector('.pill-1'); if(!root) return;
    var ribbon=root.querySelector('.pill-1__ribbon'), trail=root.querySelector('.pill-1__trail');
    if(root.getAttribute('data-state')!==state) root.setAttribute('data-state',state);
    var entered = state!==lastState; lastState=state;
    if(state==='done'){ if(entered){ setD(trail,flat()); setD(ribbon,straight(CHECK)); } return; }
    if(state==='failed'){ if(entered){ setD(trail,flat()); setD(ribbon,flat()); } return; }
    if(state==='hidden' || state==='appear'){ if(entered){ setD(ribbon,flat()); setD(trail,flat()); } return; }
    level=Math.max(0,Math.min(1,+level||0));
    var amp, dphase;
    if(state==='listening'){
      lv += (level-lv) * (level>lv ? 0.5 : 0.15);
      lvTrail += (lv-lvTrail) * 0.08;
      amp = 1.5 + lv*10.5;
      dphase = 0.32 + lv*0.45;
    } else { // transcribing / transforming / searching: calm carrier, dashes do the talking
      lv += (0.2-lv)*0.1; lvTrail += (lv-lvTrail)*0.1;
      amp = 3.5; dphase = 0.16;
    }
    if(reduce){ amp*=0.6; dphase*=0.25; }
    phase += dphase; if(phase>6283) phase-=6283;
    setD(ribbon, wave(amp, phase));
    setD(trail, wave((state==='listening' ? 1.5+lvTrail*10.5 : 3.5)*0.7, phase-0.7));
  };

  // optional helper: host fills the preview before switching to done/failed
  window.pill1_setPreview=function(text, kind, title){
    var root=document.querySelector('.pill-1'); if(!root) return;
    root.setAttribute('data-kind', kind==='search' ? 'search' : 'text');
    var t=root.querySelector('.pill-1__text'); if(t) t.textContent=text||'';
    var ct=root.querySelector('.pill-1__card-title'); if(ct) ct.textContent=title||'';
    var cb=root.querySelector('.pill-1__card-body'); if(cb) cb.textContent=kind==='search' ? (text||'') : '';
  };
})();

