/* ===== Orbit — .pill-2 =====
   Host writes --lv (0..1 smoothed level) and --ph (deg) via pill2_tick.
   Tokens only: --bg --fg --muted --accent --ok --warn --err --shadow */
.pill-2 { --p2-ease: cubic-bezier(.2,.9,.25,1.15); --p2-r: calc(10px + var(--lv) * 7px);
  position: relative; display: flex; flex-direction: column; align-items: center; gap: 8px;
  width: max-content; max-width: 260px; color: var(--fg);
  font: 500 13px/1.25 -apple-system, "SF Pro Text", "PingFang HK", "Helvetica Neue", system-ui, sans-serif;
  -webkit-font-smoothing: antialiased; user-select: none; pointer-events: auto;
  transform: translateY(0) scale(1); opacity: 1;
  transition: opacity .22s ease, transform .28s var(--p2-ease), max-width .3s ease; }

/* capsule */
.pill-2 .p2-capsule { display: flex; align-items: center; gap: 8px; height: 44px; padding: 0 12px 0 6px;
  border-radius: 22px; background: var(--bg); color: var(--fg);
  box-shadow: 0 8px 28px var(--shadow), 0 0 0 0.5px color-mix(in srgb, var(--fg) 14%, transparent) inset;
  max-width: 260px; overflow: hidden; transition: max-width .3s ease, box-shadow .3s ease; }

/* orbital cell */
.pill-2 .p2-orbit { position: relative; width: 36px; height: 36px; flex: none; display: grid; place-items: center; }
.pill-2 .p2-halo { position: absolute; inset: 6px; border-radius: 50%; background: var(--accent);
  opacity: calc(.08 + var(--lv) * .32); transform: scale(calc(.9 + var(--lv) * .9)); filter: blur(4px);
  transition: opacity .25s ease; }
.pill-2 .p2-ring { position: absolute; inset: 0; transform: rotate(var(--ph)); will-change: transform; }
.pill-2 .p2-ring-b { transform: rotate(calc(var(--ph) * -0.62)); }
.pill-2 .p2-dot { position: absolute; left: 50%; top: 50%; width: 4px; height: 4px; margin: -2px 0 0 -2px; border-radius: 50%;
  background: var(--fg); opacity: calc(.45 + var(--lv) * .55);
  transform: rotate(var(--a)) translateX(var(--p2-r)); }
.pill-2 .p2-ring-b .p2-dot { width: 3px; height: 3px; margin: -1.5px 0 0 -1.5px; background: var(--accent);
  transform: rotate(var(--a)) translateX(calc(var(--p2-r) + 5px)); }
.pill-2 .p2-glyph { position: absolute; color: var(--fg); opacity: 0; transform: scale(.6);
  transition: opacity .2s ease, transform .3s var(--p2-ease), color .2s ease; }

/* label */
.pill-2 .p2-label { position: relative; display: grid; min-width: 0; }
.pill-2 .p2-status, .pill-2 .p2-text { grid-area: 1 / 1; white-space: nowrap; opacity: 0; transform: translateY(4px);
  transition: opacity .2s ease, transform .25s var(--p2-ease); }
.pill-2 .p2-status { color: var(--muted); letter-spacing: .01em; }
.pill-2 .p2-text { color: var(--fg); overflow: hidden; text-overflow: ellipsis; max-width: 280px; }

/* close */
.pill-2 .p2-close { flex: none; width: 18px; height: 18px; border: 0; border-radius: 50%; padding: 0; display: grid; place-items: center;
  background: color-mix(in srgb, var(--fg) 10%, transparent); color: var(--muted); cursor: pointer; opacity: 0; transform: scale(.8);
  transition: opacity .2s ease, transform .2s var(--p2-ease), background .15s ease; }
.pill-2 .p2-close:hover { background: color-mix(in srgb, var(--fg) 18%, transparent); color: var(--fg); }
.pill-2:hover .p2-close, .pill-2[data-state="done"] .p2-close, .pill-2[data-state="failed"] .p2-close { opacity: 1; transform: scale(1); }

/* result card (search) */
.pill-2 .p2-card { display: none; width: 340px; max-width: 340px; padding: 10px 14px 12px; border-radius: 14px; background: var(--bg); color: var(--fg);
  box-shadow: 0 10px 32px var(--shadow), 0 0 0 0.5px color-mix(in srgb, var(--fg) 14%, transparent) inset;
  opacity: 0; transform: translateY(10px) scale(.97); transition: opacity .25s ease, transform .3s var(--p2-ease); }
.pill-2 .p2-card-kicker { font-size: 11px; color: var(--accent); font-weight: 600; letter-spacing: .04em; margin-bottom: 3px; }
.pill-2 .p2-card-title { font-weight: 600; font-size: 13px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.pill-2 .p2-card-snippet { font-weight: 400; font-size: 12px; color: var(--muted); line-height: 1.4; margin-top: 3px;
  display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }

/* ---------- states ---------- */
/* idle-appear */
.pill-2[data-state="idle-appear"] { animation: p2-appear .32s var(--p2-ease) both; }
.pill-2[data-state="idle-appear"] .p2-s-idle, .pill-2[data-state="idle-appear"] .p2-glyph-mic { opacity: 1; transform: none; }
.pill-2[data-state="idle-appear"] .p2-dot { opacity: .35; }
@keyframes p2-appear { from { opacity: 0; transform: translateY(10px) scale(.94); } to { opacity: 1; transform: none; } }

/* listening: no transitions on the live transforms (host drives them at 30 Hz) */
.pill-2[data-state="listening"] .p2-ring, .pill-2[data-state="listening"] .p2-dot { transition: none; }
.pill-2[data-state="listening"] .p2-s-listening, .pill-2[data-state="listening"] .p2-glyph-mic { opacity: 1; transform: none; }
.pill-2[data-state="listening"] .p2-glyph-mic { color: color-mix(in srgb, var(--fg) 70%, var(--accent)); }

/* transcribing: rings unwind, dots fall onto the baseline as an ellipsis */
.pill-2[data-state="transcribing"] .p2-ring, .pill-2[data-state="done"] .p2-ring, .pill-2[data-state="failed"] .p2-ring { transform: rotate(0deg); transition: transform .45s var(--p2-ease); }
.pill-2[data-state="transcribing"] .p2-dot { transform: translate(var(--tx), 13px); opacity: .9; background: var(--fg);
  transition: transform .45s var(--p2-ease), opacity .3s ease, background .3s ease;
  animation: p2-bounce 1.1s ease-in-out infinite; animation-delay: calc((var(--tx) + 10px) * .018s); }
.pill-2[data-state="transcribing"] .p2-halo { opacity: 0; }
.pill-2[data-state="transcribing"] .p2-s-transcribing, .pill-2[data-state="transcribing"] .p2-glyph-mic { opacity: 1; transform: none; }
.pill-2[data-state="transcribing"] .p2-glyph-mic { color: var(--muted); transform: translateY(-5px) scale(.9); }
@keyframes p2-bounce { 0%,100% { margin-top: -2px; } 50% { margin-top: -5px; } }

/* transforming: sparkle at the centre, calm accent orbit */
.pill-2[data-state="transforming"] .p2-ring, .pill-2[data-state="transforming"] .p2-dot, .pill-2[data-state="searching"] .p2-ring, .pill-2[data-state="searching"] .p2-dot { transition: none; }
.pill-2[data-state="transforming"] .p2-dot { background: var(--accent); opacity: .85; }
.pill-2[data-state="transforming"] .p2-halo { opacity: .22; transform: scale(1.1); animation: p2-breathe 1.6s ease-in-out infinite; }
.pill-2[data-state="transforming"] .p2-s-transforming, .pill-2[data-state="transforming"] .p2-glyph-wand { opacity: 1; transform: none; }
.pill-2[data-state="transforming"] .p2-glyph-wand { color: var(--accent); }
@keyframes p2-breathe { 0%,100% { opacity: .16; transform: scale(1); } 50% { opacity: .3; transform: scale(1.25); } }

/* searching: magnifier, wide orbit, alternating fg/accent dots */
.pill-2[data-state="searching"] { --p2-r: 14px; }
.pill-2[data-state="searching"] .p2-dot { opacity: .8; }
.pill-2[data-state="searching"] .p2-halo { opacity: .14; transform: scale(1.3); }
.pill-2[data-state="searching"] .p2-s-searching, .pill-2[data-state="searching"] .p2-glyph-search { opacity: 1; transform: none; }
.pill-2[data-state="searching"] .p2-glyph-search { color: var(--accent); }

/* done: dots converge to one point that becomes the check; preview slides in; pill may widen */
.pill-2[data-state="done"], .pill-2[data-state="done"] .p2-capsule { max-width: 340px; }
.pill-2[data-state="done"] .p2-dot { transform: translate(0,0) scale(.2); opacity: 0; background: var(--ok);
  transition: transform .35s var(--p2-ease), opacity .25s ease .1s, background .2s ease; }
.pill-2[data-state="done"] .p2-halo { background: var(--ok); opacity: .2; transform: scale(1); transition: opacity .3s ease, background .2s ease; }
.pill-2[data-state="done"] .p2-glyph-check { opacity: 1; transform: none; color: var(--ok); transition-delay: .18s; }
.pill-2[data-state="done"] .p2-text { opacity: 1; transform: none; transition-delay: .15s; }
.pill-2[data-state="done"][data-mode="search"] .p2-card { display: block; opacity: 1; transform: none; }
.pill-2[data-state="done"][data-mode="search"] .p2-capsule .p2-text { color: var(--muted); }

/* failed: dots scatter outward in --err */
.pill-2[data-state="failed"] .p2-dot { transform: rotate(var(--a)) translateX(24px) scale(.6); opacity: 0; background: var(--err);
  transition: transform .4s ease-out, opacity .35s ease .05s, background .1s ease; }
.pill-2[data-state="failed"] .p2-halo { background: var(--err); opacity: .18; transform: scale(1); }
.pill-2[data-state="failed"] .p2-glyph-fail { opacity: 1; transform: none; color: var(--err); }
.pill-2[data-state="failed"] .p2-text { opacity: 1; transform: none; color: var(--err); }
.pill-2[data-state="failed"] .p2-capsule { box-shadow: 0 8px 28px var(--shadow), 0 0 0 1px color-mix(in srgb, var(--err) 45%, transparent) inset; }
.pill-2[data-state="failed"] { animation: p2-shake .32s ease-out; }
@keyframes p2-shake { 0%,100% { transform: translateX(0); } 30% { transform: translateX(-4px); } 60% { transform: translateX(3px); } }

/* cancel / hide */
.pill-2[data-state="hidden"] { opacity: 0; transform: translateY(8px) scale(.94); pointer-events: none; }

/* ---------- reduced motion ---------- */
@media (prefers-reduced-motion: reduce) {
  .pill-2, .pill-2 * { animation: none !important; }
  .pill-2 .p2-ring, .pill-2 .p2-ring-b { transform: none !important; transition: none !important; }
  .pill-2 .p2-dot { transition: opacity .2s ease, background .2s ease !important; }
  .pill-2 .p2-halo { transform: scale(1.1); transition: opacity .15s ease; filter: blur(3px); }
  .pill-2[data-state="transcribing"] .p2-dot { transform: translate(var(--tx), 13px); }
  .pill-2[data-state="done"] .p2-dot, .pill-2[data-state="failed"] .p2-dot { transform: none; }
  .pill-2 .p2-glyph, .pill-2 .p2-status, .pill-2 .p2-text, .pill-2 .p2-card { transition-duration: .12s; transform: none; }
}

