/* Orbit — host calls window.pill2_tick(level, state) at 30 Hz. No timers here. */
(function () {
  var reduce = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
  var sm = 0;        // smoothed level 0..1 (fast attack, slow release)
  var ph = 0;        // orbit phase in degrees, accumulated
  var last = '';
  var ORBITING = { 'idle-appear': 1, listening: 1, transforming: 1, searching: 1 };

  window.pill2_tick = function (level, state) {
    var els = document.querySelectorAll('.pill-2');
    if (!els.length) return;
    level = Math.max(0, Math.min(1, +level || 0));
    sm += (level > sm ? 0.45 : 0.10) * (level - sm);

    if (state && state !== last) {
      last = state;
      ph = ((ph % 360) + 360) % 360;      // normalise so the unwind on collapse is at most one turn
      if (state === 'transcribing' || state === 'done' || state === 'failed') ph = 0; // CSS overrides ring rotation anyway
      for (var j = 0; j < els.length; j++) els[j].setAttribute('data-state', state);
    }

    if (ORBITING[last] && !reduce) {
      // Listening: speed follows the voice. Transforming/searching: calm constant drift.
      var drive = last === 'listening' ? sm : (last === 'searching' ? 0.35 : 0.22);
      ph += 1.4 + Math.pow(drive, 0.8) * 9.5;   // 1.4..10.9 deg per tick => ~7.5 s .. ~1.1 s per revolution
      if (ph > 3.6e6) ph -= 3.6e6;
    }

    var lv = (last === 'listening' ? sm : 0).toFixed(3);
    var phs = ph.toFixed(1) + 'deg';
    for (var i = 0; i < els.length; i++) {
      var s = els[i].style;
      s.setProperty('--lv', lv);
      s.setProperty('--ph', phs);
    }
  };

  /* Optional helpers for the host: set the preview text / search card content. */
  window.pill2_setText = function (text) {
    var t = document.querySelectorAll('.pill-2 .p2-text');
    for (var i = 0; i < t.length; i++) t[i].textContent = text || '';
  };
  window.pill2_setSearch = function (title, snippet) {
    var els = document.querySelectorAll('.pill-2');
    for (var i = 0; i < els.length; i++) {
      var e = els[i];
      if (title == null) { e.removeAttribute('data-mode'); continue; }
      e.setAttribute('data-mode', 'search');
      var c = e.querySelector('.p2-card');
      c.querySelector('.p2-card-title').textContent = title || '';
      c.querySelector('.p2-card-snippet').textContent = snippet || '';
      c.setAttribute('aria-hidden', 'false');
    }
  };
})();

