.pill-3[data-state="done"] .pill-3__label,.pill-3[data-state="failed"] .pill-3__label{padding-left:0;font-size:11px;text-transform:uppercase;letter-spacing:.06em;line-height:18px}
.pill-3[data-state="done"] .pill-3__glyph,.pill-3[data-state="failed"] .pill-3__glyph{opacity:1}
.pill-3[data-state="done"] .pill-3__text,.pill-3[data-state="failed"] .pill-3__text{flex-basis:100%;opacity:1;-webkit-line-clamp:3;color:var(--fg)}
