.pill-3[data-state="cancel"],.pill-3[data-state="hide"]{animation:pill3-melt .26s ease-in both;pointer-events:none}

/* ---- reduced motion: no ripple, no orbit; level becomes bead opacity only ---- */
@media (prefers-reduced-motion:reduce){
