  .pill-3[data-state="cancel"],.pill-3[data-state="hide"]{opacity:0}
  .pill-3 .pill-3__b1{opacity:calc(.5 + var(--lv,0)*.5)}
  .pill-3 .pill-3__ring{stroke-dasharray:none}
}

