window.pill3_tick = function (level, state) {
  var root = document.querySelector('.pill-3');
  if (!root) return;
  var m = root._p3 || (root._p3 = { lv: -1, st: '', sm: 0, disp: root.querySelector('#pill3-disp'), b1: root.querySelector('.pill-3__b1'), b2: root.querySelector('.pill-3__b2'), b3: root.querySelector('.pill-3__b3'), rm: matchMedia('(prefers-reduced-motion: reduce)').matches });
  if (state && state !== m.st) { m.st = state; root.setAttribute('data-state', state); }
  var l = Math.max(0, Math.min(1, +level || 0));
  m.sm += (l - m.sm) * (l > m.sm ? 0.55 : 0.18);          /* fast attack, slow release */
  if (Math.abs(m.sm - m.lv) < 0.01) return;               /* skip DOM writes when nothing moved */
  m.lv = m.sm;
  root.style.setProperty('--lv', m.lv.toFixed(3));
  if (m.rm || (state !== 'listening' && state !== 'idle-appear')) { if (m.disp) m.disp.setAttribute('scale', '0'); return; }
  if (m.disp) m.disp.setAttribute('scale', (2 + m.lv * 16).toFixed(1));
  /* breathe the three beads apart with level so the metaball necks stretch */
  var r = 11 + m.lv * 7, sp = 6 + m.lv * 10;
  if (m.b1) { m.b1.setAttribute('r', r.toFixed(1)); m.b1.setAttribute('cx', (30 - sp * 0.5).toFixed(1)); }
  if (m.b2) { m.b2.setAttribute('r', (r * 0.85).toFixed(1)); m.b2.setAttribute('cx', (30 + sp).toFixed(1)); m.b2.setAttribute('cy', (32 - sp * 0.4).toFixed(1)); }
  if (m.b3) { m.b3.setAttribute('r', (r * 0.7).toFixed(1)); m.b3.setAttribute('cx', (30 + sp * 0.4).toFixed(1)); m.b3.setAttribute('cy', (32 + sp * 0.6).toFixed(1)); }
};
/* Host sets text via: el.querySelector('[data-label]').dataset.label = 'Listening'; el.querySelector('[data-text]').dataset.text = preview; */

