/* Ghostwriter — .pill-5 ------------------------------------------------ */
.pill-5{
  --p5-level:0;
  --p5-ease:cubic-bezier(.2,.8,.2,1);
  position:relative; box-sizing:border-box;
  width:240px; min-height:48px; max-width:260px;
  padding:9px 14px 8px 12px;
  border-radius:16px;
  background:var(--bg); color:var(--fg);
  box-shadow:0 10px 28px var(--shadow), 0 0 0 .5px var(--muted);
  font:500 14px/1.25 -apple-system,"SF Pro Text",system-ui,sans-serif;
  -webkit-font-smoothing:antialiased;
  transition:width .34s var(--p5-ease), max-width .34s var(--p5-ease), opacity .22s ease, transform .26s var(--p5-ease);
  transform-origin:50% 100%;
  overflow:hidden;
}
.pill-5__row{display:flex; align-items:center; gap:9px; height:22px;}
.pill-5__mic{
  flex:none; width:15px; height:15px; color:var(--fg);
  opacity:calc(.45 + var(--p5-level) * .55);
  transition:opacity .12s linear, color .3s;
}
.pill-5__line{flex:1 1 auto; min-width:0; height:22px; overflow:hidden; position:relative;}
.pill-5__line::before{ /* soft left fade so scrolled-off ghost text dissolves */
  content:""; position:absolute; left:0; top:0; bottom:0; width:18px; z-index:1; pointer-events:none;
  background:linear-gradient(90deg, var(--bg), transparent);
}
.pill-5__scroll{
  display:flex; align-items:center; height:22px; white-space:nowrap;
  will-change:transform; transition:transform .09s linear;
}
.pill-5__ghost{display:inline-flex; align-items:center; gap:0; height:22px;}
.pill-5__ghost b{ /* one ghost "syllable" stroke */
  display:inline-block; height:9px; width:10px; border-radius:3px;
  background:var(--fg); opacity:.28; margin-right:3px;
  transform-origin:0 50%;
  animation:p5-type .16s var(--p5-ease) both;
  transition:opacity .3s, background-color .3s, height .3s;
}
.pill-5__ghost b.sp{width:6px; background:transparent; opacity:0; margin:0;} /* word gap */
.pill-5__ghost b.set{opacity:1; height:11px;}                            /* solidified beat */
.pill-5__text{
  display:inline-block; color:var(--fg); max-width:100%;
  opacity:0; transform:translateY(3px);
  transition:opacity .28s ease, transform .28s var(--p5-ease), color .3s;
  overflow:hidden; text-overflow:ellipsis;
}
.pill-5__caret{
  flex:none; position:relative; width:2px; height:16px; margin-left:1px;
  background:var(--muted); border-radius:1px; overflow:hidden;
  animation:p5-blink 1.05s steps(1,end) infinite;
}
.pill-5__caret i{ /* accent ink rising with audio level */
  position:absolute; left:0; right:0; bottom:0; height:100%;
  background:var(--accent); transform-origin:50% 100%;
  transform:scaleY(var(--p5-level)); transition:transform .08s linear;
}
.pill-5__badge{flex:none; width:16px; height:16px; position:relative; display:none;}
.pill-5__ico{position:absolute; inset:0; width:16px; height:16px; opacity:0; transform:scale(.6); transition:opacity .2s, transform .28s var(--p5-ease);}
.pill-5__rule{height:1px; margin-top:6px; border-radius:1px; background:var(--muted); opacity:.35; position:relative; overflow:hidden; transition:opacity .3s, background-color .3s;}
.pill-5__rule i{
  position:absolute; inset:0; background:var(--accent);
  transform-origin:0 50%; transform:scaleX(var(--p5-level));
  transition:transform .1s linear, background-color .3s;
}
.pill-5__card{display:none; margin-top:8px; padding-top:8px; border-top:.5px solid var(--muted); color:var(--fg);}
.pill-5__card-title{font-weight:600; font-size:13px; margin-bottom:3px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;}
.pill-5__card-body{font-weight:400; font-size:12.5px; line-height:1.35; color:var(--muted); display:-webkit-box; -webkit-line-clamp:3; -webkit-box-orient:vertical; overflow:hidden;}

/* ---- states ---------------------------------------------------------- */
.pill-5[data-state="idle-appear"]{animation:p5-in .32s var(--p5-ease) both;}
.pill-5[data-state="idle-appear"] .pill-5__caret{animation:none; opacity:.6;}

.pill-5[data-state="listening"] .pill-5__mic{color:var(--accent);}

.pill-5[data-state="transcribing"] .pill-5__caret{animation:none; opacity:0;}
.pill-5[data-state="transcribing"] .pill-5__ghost{animation:p5-wash 1.1s ease-in-out infinite;}
.pill-5[data-state="transcribing"] .pill-5__rule i{transform:scaleX(1); animation:p5-sweep 1.1s var(--p5-ease) infinite; background:var(--fg); opacity:.5;}
.pill-5[data-state="transcribing"] .pill-5__mic{opacity:.4;}

.pill-5[data-state="transforming"] .pill-5__caret{animation:none; opacity:0;}
.pill-5[data-state="transforming"] .pill-5__ghost b{background:var(--accent); opacity:.45;}
.pill-5[data-state="transforming"] .pill-5__ghost{animation:p5-wash 1.1s ease-in-out infinite;}
.pill-5[data-state="transforming"] .pill-5__rule i{transform:scaleX(1); animation:p5-sweep 1.1s var(--p5-ease) infinite alternate;}
.pill-5[data-state="transforming"] .pill-5__badge{display:block; color:var(--accent);}
.pill-5[data-state="transforming"] .pill-5__ico--spark{opacity:1; transform:scale(1); animation:p5-spin 2.4s linear infinite;}

.pill-5[data-state="searching"]{width:260px;}
.pill-5[data-state="searching"] .pill-5__caret{animation:none; opacity:0;}
.pill-5[data-state="searching"] .pill-5__ghost{opacity:.6;}
.pill-5[data-state="searching"] .pill-5__text{opacity:1; transform:none; color:var(--muted);}
.pill-5[data-state="searching"] .pill-5__badge{display:block; color:var(--accent);}
.pill-5[data-state="searching"] .pill-5__ico--search{opacity:1; transform:scale(1);}
.pill-5[data-state="searching"] .pill-5__rule{opacity:1; background:transparent;}
.pill-5[data-state="searching"] .pill-5__rule i{
  transform:scaleX(1);
  background:repeating-linear-gradient(90deg, var(--accent) 0 6px, transparent 6px 12px);
  animation:p5-crawl .5s linear infinite;
}

.pill-5[data-state="done"]{width:340px; max-width:380px;}
.pill-5[data-state="done"] .pill-5__scroll{transform:none !important;}
.pill-5[data-state="done"] .pill-5__ghost{display:none;}
.pill-5[data-state="done"] .pill-5__text{opacity:1; transform:none;}
.pill-5[data-state="done"] .pill-5__caret{animation:none; opacity:0;}
.pill-5[data-state="done"] .pill-5__mic{color:var(--ok); opacity:1;}
.pill-5[data-state="done"] .pill-5__badge{display:block; color:var(--ok);}
.pill-5[data-state="done"] .pill-5__ico--ok{opacity:1; transform:scale(1);}
.pill-5[data-state="done"] .pill-5__rule{background:var(--ok); opacity:.9; animation:p5-settle 1.4s ease-out .3s both;}
.pill-5[data-state="done"] .pill-5__rule i{transform:scaleX(0);}
.pill-5[data-state="done"][data-kind="search"]{width:380px; max-width:400px;}
.pill-5[data-state="done"][data-kind="search"] .pill-5__card{display:block;}
.pill-5[data-state="done"][data-kind="search"] .pill-5__badge{color:var(--accent);}
.pill-5[data-state="done"][data-kind="search"] .pill-5__ico--ok{opacity:0;}
.pill-5[data-state="done"][data-kind="search"] .pill-5__ico--search{opacity:1; transform:scale(1);}

.pill-5[data-state="failed"]{width:300px; max-width:340px; animation:p5-nudge .32s var(--p5-ease);}
.pill-5[data-state="failed"] .pill-5__ghost{display:none;}
.pill-5[data-state="failed"] .pill-5__text{opacity:1; transform:none; color:var(--err);}
.pill-5[data-state="failed"] .pill-5__caret{animation:none; opacity:0;}
.pill-5[data-state="failed"] .pill-5__mic{color:var(--err); opacity:1;}
.pill-5[data-state="failed"] .pill-5__badge{display:block; color:var(--err);}
.pill-5[data-state="failed"] .pill-5__ico--err{opacity:1; transform:scale(1);}
.pill-5[data-state="failed"] .pill-5__rule{background:var(--err); opacity:.9;}
.pill-5[data-state="failed"] .pill-5__rule i{transform:scaleX(0);}

.pill-5[data-state="hidden"]{opacity:0; transform:translateY(8px) scale(.97); pointer-events:none;}

/* ---- keyframes ------------------------------------------------------- */
@keyframes p5-in{from{opacity:0; transform:translateY(10px) scale(.96);} to{opacity:1; transform:none;}}
@keyframes p5-type{from{transform:scaleX(.2); opacity:0;} to{transform:none;}}
@keyframes p5-blink{0%,55%{opacity:1;} 56%,100%{opacity:.15;}}
@keyframes p5-wash{0%,100%{opacity:1;} 50%{opacity:.45;}}
@keyframes p5-sweep{0%{transform:translateX(-100%) scaleX(.5);} 100%{transform:translateX(100%) scaleX(.5);}}
@keyframes p5-crawl{from{background-position:0 0;} to{background-position:12px 0;}}
@keyframes p5-spin{to{transform:scale(1) rotate(360deg);}}
@keyframes p5-settle{from{opacity:.9;} to{opacity:.3;}}
@keyframes p5-nudge{0%,100%{transform:none;} 30%{transform:translateX(-3px);} 60%{transform:translateX(3px);}}

/* ---- reduced motion -------------------------------------------------- */
@media (prefers-reduced-motion: reduce){
  .pill-5, .pill-5 *{animation:none !important; transition:none !important;}
  .pill-5 .pill-5__scroll{transition:none;}
  .pill-5 .pill-5__caret{opacity:1;}
  .pill-5 .pill-5__ghost b{animation:none; transform:none;}
  .pill-5[data-state="transcribing"] .pill-5__rule i,
  .pill-5[data-state="transforming"] .pill-5__rule i{transform:scaleX(1); opacity:.6;}
  .pill-5[data-state="searching"] .pill-5__rule i{background:var(--accent);}
  .pill-5[data-state="hidden"]{transform:none;}
}

js:
// Host calls window.pill5_tick(level, state) at 30 Hz. No timers here.
// Host also sets data-text (transcript / message / query) and, for web-search
// results, data-kind="search" plus data-title / data-body on the root element.
(function(){
  var S = { el:null, acc:0, marks:[], widths:0, sinceGap:0, wordLen:0, prevState:null, frame:0, setBeat:0, seed:1 };
  var MAX_MARKS = 44;
  function rnd(){ S.seed = (S.seed * 16807) % 2147483647; return (S.seed - 1) / 2147483646; }
  function root(){ if(!S.el || !S.el.isConnected) S.el = document.querySelector('.pill-5'); return S.el; }
  function reduced(){ return window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches; }

  function clearGhost(el){
    var g = el.querySelector('.pill-5__ghost'); g.textContent = '';
    S.marks = []; S.widths = 0; S.acc = 0; S.sinceGap = 0; S.wordLen = 0;
    el.querySelector('.pill-5__scroll').style.transform = '';
  }
  function pushMark(el, level){
    var g = el.querySelector('.pill-5__ghost');
    var b = document.createElement('b'), w;
    var gap = S.sinceGap >= S.wordLen;
    if(gap){ b.className = 'sp'; w = 6; S.sinceGap = 0; S.wordLen = 2 + Math.floor(rnd()*4); }
    else { w = Math.round(6 + level*12 + rnd()*4); b.style.width = w + 'px'; b.style.height = Math.round(8 + level*3) + 'px'; S.sinceGap++; }
    g.appendChild(b); S.marks.push(w + (gap?0:3)); S.widths += w + (gap?0:3);
    while(S.marks.length > MAX_MARKS){ S.widths -= S.marks.shift(); g.removeChild(g.firstChild); }
    // Typewriter carriage: keep the caret on-screen by sliding old ghost text left.
    var line = el.querySelector('.pill-5__line');
    var avail = line.clientWidth - 8;
    var shift = Math.max(0, S.widths - avail);
    el.querySelector('.pill-5__scroll').style.transform = shift ? 'translateX(-' + shift + 'px)' : '';
  }
  function syncText(el, state){
    var t = el.querySelector('.pill-5__text');
    var txt = el.getAttribute('data-text') || '';
    if(state === 'searching' && txt) txt = txt;                 // shows the query
    if(state === 'failed' && !txt) txt = 'Could not transcribe';
    if(t.textContent !== txt) t.textContent = txt;
    var card = el.querySelector('.pill-5__card');
    if(card){
      var ti = el.getAttribute('data-title') || '', bo = el.getAttribute('data-body') || '';
      var tt = card.querySelector('.pill-5__card-title'), bb = card.querySelector('.pill-5__card-body');
      if(tt.textContent !== ti) tt.textContent = ti;
      if(bb.textContent !== bo) bb.textContent = bo;
    }
  }
  function enter(el, state){
    if(state === 'idle-appear' || state === 'listening'){ if(S.prevState !== 'idle-appear' || state === 'idle-appear') clearGhost(el); }
    if(state === 'done'){
      // Solidify beat: ghost strokes go full-ink for ~10 frames, then the real text replaces them.
      var g = el.querySelector('.pill-5__ghost');
      if(!reduced() && g.children.length){ g.style.display = 'inline-flex'; for(var i=0;i<g.children.length;i++) g.children[i].classList.add('set'); S.setBeat = 10; }
      else S.setBeat = 0;
    } else {
      var g2 = el.querySelector('.pill-5__ghost'); g2.style.display = ''; S.setBeat = 0;
    }
  }

  window.pill5_tick = function(level, state){
    var el = root(); if(!el) return;
    level = Math.max(0, Math.min(1, +level || 0));
    state = state || el.getAttribute('data-state') || 'listening';
    if(el.getAttribute('data-state') !== state) el.setAttribute('data-state', state);
    if(state !== S.prevState){ enter(el, state); S.prevState = state; }
    S.frame++;

    // Level drives caret ink, mic opacity and the rule fill (CSS reads --p5-level).
    var shown = state === 'listening' ? level : 0;
    el.style.setProperty('--p5-level', shown.toFixed(3));

    if(state === 'listening'){
      // Typing cadence: ~0 marks/s in silence, ~14 marks/s at full level; width grows with level.
      var gate = level < 0.06 ? 0 : level;
      S.acc += 0.05 + gate * 0.42;
      if(S.acc >= 1){ S.acc -= 1; pushMark(el, level); }
      // If host streams partial text while listening, show it as ghost words instead.
      var partial = el.getAttribute('data-text');
      var t = el.querySelector('.pill-5__text');
      if(partial){ if(t.textContent !== partial) t.textContent = partial; t.style.opacity = '.4'; t.style.transform = 'none'; }
      else if(t.style.opacity){ t.style.opacity = ''; t.style.transform = ''; t.textContent = ''; }
    } else {
      var t2 = el.querySelector('.pill-5__text'); if(t2.style.opacity){ t2.style.opacity = ''; t2.style.transform = ''; }
    }

    if(state === 'done'){
      if(S.setBeat > 0){ S.setBeat--; if(S.setBeat === 0){ el.querySelector('.pill-5__ghost').style.display = ''; } }
    }
    if(state === 'done' || state === 'failed' || state === 'searching') syncText(el, state);
  };
})();

css:
.pill-6{
  --p6-level:0;
  --p6-r:220px;
  position:relative;
  display:inline-grid;
  place-items:center;
  width:var(--p6-r);
  height:44px;
  padding:34px 40px;
  box-sizing:content-box;
  font:500 13px/1.3 -apple-system,BlinkMacSystemFont,"SF Pro Text","PingFang HK",sans-serif;
  color:var(--fg);
  transition:width .28s cubic-bezier(.2,.8,.2,1),height .28s cubic-bezier(.2,.8,.2,1),opacity .18s ease;
}
.pill-6__halo{
  position:absolute;
  left:50%;top:50%;
  width:300px;height:140px;
  border-radius:50%;
  pointer-events:none;
  transform:translate(-50%,-50%) scale(calc(.55 + var(--p6-level) * .7));
  opacity:calc(.22 + var(--p6-level) * .55);
  transition:transform .08s linear,opacity .08s linear;
  will-change:transform,opacity;
}
.pill-6__halo--a{
  background:radial-gradient(closest-side,var(--accent) 0%,transparent 72%);
}
.pill-6__halo--b{
  background:radial-gradient(closest-side,var(--ok) 0%,transparent 72%);
  opacity:calc(var(--p6-level) * var(--p6-level) * .6);
}
.pill-6__body{
  position:relative;
  z-index:1;
  display:flex;
  align-items:center;
  gap:8px;
  width:100%;height:100%;
  padding:0 14px;
  box-sizing:border-box;
  border-radius:22px;
  background:var(--bg);
  box-shadow:0 0 0 .5px var(--shadow),0 8px 24px -8px var(--shadow);
  overflow:hidden;
  white-space:nowrap;
}
.pill-6__glyph{flex:none;color:var(--accent)}
.pill-6__label{color:var(--muted);letter-spacing:.01em}
.pill-6__label::after{content:"Listening"}
.pill-6__text{
  display:none;
  flex:1;
  min-width:0;
  overflow:hidden;
  text-overflow:ellipsis;
  color:var(--fg);
}

/* idle-appear */
.pill-6[data-state="idle-appear"]{opacity:1;animation:p6-appear .22s cubic-bezier(.2,.8,.2,1) both}
.pill-6[data-state="idle-appear"] .pill-6__halo{transform:translate(-50%,-50%) scale(.4);opacity:.12}
.pill-6[data-state="idle-appear"] .pill-6__label::after{content:"Hold ⌥ to talk"}
@keyframes p6-appear{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}

/* transcribing: slow muted breath, no level */
.pill-6[data-state="transcribing"] .pill-6__glyph{color:var(--muted)}
.pill-6[data-state="transcribing"] .pill-6__label::after{content:"Transcribing…"}
.pill-6[data-state="transcribing"] .pill-6__halo--b{opacity:0}
.pill-6[data-state="transcribing"] .pill-6__halo--a{animation:p6-breathe 1.6s ease-in-out infinite;transition:none}
@keyframes p6-breathe{0%,100%{transform:translate(-50%,-50%) scale(.5);opacity:.18}50%{transform:translate(-50%,-50%) scale(.72);opacity:.34}}

/* transforming: two hues sweep alternately */
.pill-6[data-state="transforming"] .pill-6__label::after{content:"Rewriting…"}
.pill-6[data-state="transforming"] .pill-6__halo{transition:none;transform:translate(-50%,-50%) scale(.8)}
.pill-6[data-state="transforming"] .pill-6__halo--a{animation:p6-sweep 2.2s ease-in-out infinite}
.pill-6[data-state="transforming"] .pill-6__halo--b{animation:p6-sweep 2.2s ease-in-out infinite reverse}
@keyframes p6-sweep{0%,100%{opacity:.12;transform:translate(-62%,-50%) scale(.7)}50%{opacity:.5;transform:translate(-38%,-50%) scale(.9)}}

/* searching: wide low horizon pulse */
.pill-6[data-state="searching"] .pill-6__label::after{content:"Searching the web…"}
.pill-6[data-state="searching"] .pill-6__halo--b{opacity:0}
.pill-6[data-state="searching"] .pill-6__halo--a{transition:none;animation:p6-horizon 1.8s ease-in-out infinite}
@keyframes p6-horizon{0%,100%{transform:translate(-50%,-50%) scale(.9,.35);opacity:.25}50%{transform:translate(-50%,-50%) scale(1.25,.45);opacity:.5}}

/* done: pill grows, halo settles to ok rim */
.pill-6[data-state="done"]{--p6-r:260px;height:60px}
.pill-6[data-state="done"] .pill-6__body{border-radius:30px;box-shadow:0 0 0 1px var(--ok),0 8px 24px -8px var(--shadow)}
.pill-6[data-state="done"] .pill-6__glyph{color:var(--ok)}
.pill-6[data-state="done"] .pill-6__label{display:none}
.pill-6[data-state="done"] .pill-6__text{display:block;white-space:normal;max-height:2.6em;line-height:1.3;font-size:12.5px}
.pill-6[data-state="done"] .pill-6__halo--a{opacity:0;transition:opacity .4s ease}
.pill-6[data-state="done"] .pill-6__halo--b{transition:transform .35s cubic-bezier(.2,.8,.2,1),opacity .6s ease .15s;transform:translate(-50%,-50%) scale(.6);opacity:.12}

/* failed: err flash then faint ring */
.pill-6[data-state="failed"]{--p6-r:260px;height:60px}
.pill-6[data-state="failed"] .pill-6__body{border-radius:30px;box-shadow:0 0 0 1px var(--err),0 8px 24px -8px var(--shadow)}
.pill-6[data-state="failed"] .pill-6__glyph{color:var(--err)}
.pill-6[data-state="failed"] .pill-6__label{display:none}
.pill-6[data-state="failed"] .pill-6__text{display:block;white-space:normal;max-height:2.6em;font-size:12.5px;color:var(--fg)}
.pill-6[data-state="failed"] .pill-6__halo--b{opacity:0}
.pill-6[data-state="failed"] .pill-6__halo--a{background:radial-gradient(closest-side,var(--err) 0%,transparent 72%);transition:none;animation:p6-flash .9s ease-out both}
@keyframes p6-flash{0%{transform:translate(-50%,-50%) scale(1.1);opacity:.6}100%{transform:translate(-50%,-50%) scale(.55);opacity:.1}}

/* cancel / hide */
.pill-6[data-state="hidden"]{opacity:0;pointer-events:none;transition:opacity .14s ease}
.pill-6[data-state="hidden"] .pill-6__halo{transform:translate(-50%,-50%) scale(.3);opacity:0;transition:transform .14s ease,opacity .14s ease}

/* reduced motion: no keyframes, level maps to opacity only */
@media (prefers-reduced-motion:reduce){
  .pill-6,.pill-6 .pill-6__halo,.pill-6 .pill-6__body{animation:none!important;transition:opacity .2s ease!important}
  .pill-6 .pill-6__halo{transform:translate(-50%,-50%) scale(.7)!important}
  .pill-6[data-state="listening"] .pill-6__halo--a{opacity:calc(.2 + var(--p6-level) * .5)}
  .pill-6[data-state="transcribing"] .pill-6__halo--a,
  .pill-6[data-state="transforming"] .pill-6__halo--a,
  .pill-6[data-state="searching"] .pill-6__halo--a{opacity:.3}
  .pill-6[data-state="transforming"] .pill-6__halo--b{opacity:.2}
}

js:
window.pill6_tick = function(level, state){
  var el = document.querySelector('.pill-6');
  if(!el) return;
  var l = Math.max(0, Math.min(1, +level || 0));
  if(!el.__p6s) el.__p6s = 0;
  // fast attack, slow release so the halo feels like breath not jitter
  el.__p6s = l > el.__p6s ? el.__p6s + (l - el.__p6s) * 0.6 : el.__p6s + (l - el.__p6s) * 0.18;
  el.style.setProperty('--p6-level', el.__p6s.toFixed(3));
  if(state && el.dataset.state !== state) el.dataset.state = state;
  // host may set preview/error text by writing to .pill-6__text before switching to done/failed
};

css:
.pill-7{
  --p7-w:240px;
  --p7-tint:var(--accent);
  --p7-edge:color-mix(in srgb,var(--fg) 12%,transparent);
  --p7-halo:color-mix(in srgb,var(--p7-tint) 55%,transparent);
  position:fixed;top:0;left:50%;
  width:var(--p7-w);max-height:44px;
  transform:translate(-50%,0);
  box-sizing:border-box;overflow:hidden;
  color:var(--fg);
  background:var(--bg);
  border:1px solid var(--p7-edge);border-top:0;
  border-radius:0 0 22px 22px;
  box-shadow:0 8px 24px var(--shadow),0 1px 0 var(--p7-edge) inset;
  font:500 13px/1.3 -apple-system,"SF Pro Text","PingFang HK","PingFang TC",system-ui,sans-serif;
  -webkit-font-smoothing:antialiased;
  transition:width .32s cubic-bezier(.2,.9,.25,1.15),max-height .36s cubic-bezier(.2,.9,.25,1),transform .24s cubic-bezier(.2,.9,.25,1.2),opacity .18s ease;
  will-change:transform,max-height,width;
}
.pill-7[data-state="hidden"],.pill-7[data-state="cancel"]{transform:translate(-50%,-110%);opacity:0;pointer-events:none}
.pill-7[data-state="done"],.pill-7[data-state="failed"],.pill-7[data-state="search-result"]{--p7-w:360px;max-height:220px;border-radius:0 0 18px 18px}
.pill-7[data-state="done"]{--p7-tint:var(--ok)}
.pill-7[data-state="failed"]{--p7-tint:var(--err)}
.pill-7[data-state="transforming"]{--p7-tint:var(--warn)}

/* top hairline progress seam */
.pill-7 .p7-seam{position:absolute;top:0;left:0;right:0;height:2px;opacity:0;overflow:hidden;background:color-mix(in srgb,var(--p7-tint) 18%,transparent)}
.pill-7 .p7-seam::before{content:"";position:absolute;top:0;bottom:0;left:-40%;width:40%;background:linear-gradient(90deg,transparent,var(--p7-tint),transparent);animation:p7-sweep 1.1s linear infinite;animation-play-state:paused}
.pill-7[data-state="transcribing"] .p7-seam,.pill-7[data-state="transforming"] .p7-seam,.pill-7[data-state="searching"] .p7-seam{opacity:1}
.pill-7[data-state="transcribing"] .p7-seam::before,.pill-7[data-state="transforming"] .p7-seam::before,.pill-7[data-state="searching"] .p7-seam::before{animation-play-state:running}
@keyframes p7-sweep{to{left:100%}}

/* head row */
.pill-7 .p7-head{display:flex;align-items:center;gap:10px;height:44px;padding:0 12px 0 12px}
.pill-7 .p7-orb{position:relative;width:20px;height:20px;flex:0 0 20px;display:grid;place-items:center;color:var(--p7-tint)}
.pill-7 .p7-dot{position:relative;z-index:2;width:8px;height:8px;border-radius:50%;background:var(--p7-tint);transform:scale(calc(1 + var(--p7-level)*.35));transition:background .2s ease,transform .05s linear,opacity .2s ease}
.pill-7 .p7-ring{position:absolute;inset:0;border-radius:50%;border:1.5px solid var(--p7-halo);opacity:0;transform:scale(.6);transition:transform .06s linear,opacity .06s linear}
.pill-7 .p7-glyph{position:absolute;inset:2px;width:16px;height:16px;opacity:0;transform:scale(.6);transition:opacity .18s ease,transform .18s cubic-bezier(.2,.9,.25,1.3)}
.pill-7[data-state="listening"] .p7-ring-a{opacity:calc(.25 + var(--p7-level)*.75);transform:scale(calc(.7 + var(--p7-level)*.9))}
.pill-7[data-state="listening"] .p7-ring-b{opacity:calc(var(--p7-level)*.45);transform:scale(calc(.9 + var(--p7-level)*1.3))}
.pill-7[data-state="transcribing"] .p7-dot,.pill-7[data-state="transforming"] .p7-dot,.pill-7[data-state="searching"] .p7-dot{animation:p7-breathe 1.2s ease-in-out infinite}
@keyframes p7-breathe{0%,100%{transform:scale(.8);opacity:.55}50%{transform:scale(1.15);opacity:1}}
.pill-7[data-state="done"] .p7-dot,.pill-7[data-state="failed"] .p7-dot,.pill-7[data-state="search-result"] .p7-dot{opacity:0;transform:scale(.2)}
.pill-7[data-state="done"] .p7-glyph-ok,.pill-7[data-state="failed"] .p7-glyph-err,.pill-7[data-state="search-result"] .p7-glyph-web,.pill-7[data-state="searching"] .p7-glyph-web{opacity:1;transform:scale(1)}
.pill-7[data-state="searching"] .p7-dot{opacity:0}

.pill-7 .p7-text{flex:1 1 auto;min-width:0;position:relative;height:18px}
.pill-7 .p7-label{position:absolute;left:0;top:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%;opacity:0;transform:translateY(6px);transition:opacity .18s ease,transform .22s cubic-bezier(.2,.9,.25,1);color:var(--fg)}
.pill-7[data-state="listening"] .p7-l-listening,
.pill-7[data-state="transcribing"] .p7-l-transcribing,
.pill-7[data-state="transforming"] .p7-l-transforming,
.pill-7[data-state="searching"] .p7-l-searching,
.pill-7[data-state="search-result"] .p7-l-searching,
.pill-7[data-state="done"] .p7-l-done,
.pill-7[data-state="failed"] .p7-l-failed{opacity:1;transform:translateY(0)}
.pill-7[data-state="failed"] .p7-l-failed{color:var(--err)}
.pill-7[data-state="transcribing"] .p7-label,.pill-7[data-state="transforming"] .p7-label,.pill-7[data-state="searching"] .p7-label{color:var(--muted)}

.pill-7 .p7-key{flex:0 0 auto;font:600 11px/1 -apple-system,system-ui,sans-serif;color:var(--muted);border:1px solid var(--p7-edge);border-bottom-width:2px;border-radius:5px;padding:3px 5px;background:color-mix(in srgb,var(--fg) 4%,transparent);transition:opacity .2s ease}
.pill-7:not([data-state="listening"]) .p7-key{opacity:0}

/* expandable body */
.pill-7 .p7-body{position:relative;padding:0 14px 12px 14px;opacity:0;transform:translateY(-6px);transition:opacity .22s ease .1s,transform .26s cubic-bezier(.2,.9,.25,1) .1s}
.pill-7[data-state="done"] .p7-body,.pill-7[data-state="failed"] .p7-body,.pill-7[data-state="search-result"] .p7-body{opacity:1;transform:translateY(0)}
.pill-7 .p7-rail{position:absolute;left:14px;top:2px;bottom:12px;width:3px;border-radius:2px;background:var(--p7-tint);opacity:.9}
.pill-7 .p7-preview,.pill-7 .p7-search{margin-left:12px;display:none}
.pill-7 .p7-preview{font-weight:400;font-size:13px;line-height:1.45;color:var(--fg);max-height:120px;overflow:hidden;display:-webkit-box;-webkit-line-clamp:5;-webkit-box-orient:vertical;visibility:hidden}
.pill-7[data-state="done"] .p7-preview,.pill-7[data-state="failed"] .p7-preview{visibility:visible}
.pill-7[data-state="failed"] .p7-preview{color:var(--err)}
.pill-7[data-state="search-result"] .p7-preview{display:none}
.pill-7[data-state="search-result"] .p7-search{display:block}
.pill-7 .p7-q{font-size:12px;color:var(--muted);margin-bottom:6px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.pill-7 .p7-q::before{content:"“"}.pill-7 .p7-q::after{content:"”"}
.pill-7 .p7-results{list-style:none;margin:0;padding:0;display:grid;gap:6px}
.pill-7 .p7-results li{display:grid;gap:2px;padding:6px 8px;border-radius:8px;background:color-mix(in srgb,var(--fg) 5%,transparent)}
.pill-7 .p7-results b{font-weight:600;font-size:12.5px;color:var(--accent);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.pill-7 .p7-results span{font-weight:400;font-size:12px;line-height:1.35;color:var(--fg);display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}

@media (prefers-reduced-motion:reduce){
  .pill-7,.pill-7 *,.pill-7 .p7-seam::before{transition:none!important;animation:none!important}
  .pill-7 .p7-dot{transform:none!important;opacity:calc(.55 + var(--p7-level)*.45)}
  .pill-7 .p7-ring{display:none}
  .pill-7[data-state="transcribing"] .p7-seam,.pill-7[data-state="transforming"] .p7-seam,.pill-7[data-state="searching"] .p7-seam{background:var(--p7-tint);opacity:.6}
}

js:
window.pill7_tick = (function(){
  var smooth = 0, lastState = null;
  return function(level, state){
    var el = document.querySelector('.pill-7');
    if(!el) return;
    if(state && state !== lastState){
      // "cancel" and "hidden" both retract; "idle-appear" is just the first transition into "listening"
      el.setAttribute('data-state', state === 'idle-appear' ? 'listening' : state);
      lastState = state;
      if(state !== 'listening'){ smooth = 0; el.style.setProperty('--p7-level', '0'); }
    }
    if(el.getAttribute('data-state') !== 'listening') return;
    var v = Math.max(0, Math.min(1, +level || 0));
    // fast attack, slow release: halo snaps out on speech, relaxes back over ~10 frames
    smooth = v > smooth ? smooth + (v - smooth) * 0.6 : smooth + (v - smooth) * 0.12;
    el.style.setProperty('--p7-level', smooth.toFixed(3));
  };
})();

css:
.pill-8{
  --lvl: var(--level, 0);
  position: relative;
  display: inline-flex;
  align-items: center;
  width: 28px;
  height: 28px;
  font: 500 12px/1.4 -apple-system, BlinkMacSystemFont, "SF Pro Text", system-ui, sans-serif;
  color: var(--fg);
  transform-origin: 14px 14px;
  animation: pill8-appear 220ms cubic-bezier(.2,.9,.3,1.2);
}
@keyframes pill8-appear{
  from{ transform: scale(.55); opacity: 0; }
  to{ transform: scale(1); opacity: 1; }
}

.pill-8-anchor{
  position: relative;
  width: 28px;
  height: 28px;
  flex: 0 0 28px;
  z-index: 2;
}

/* base disc: HUD material dot, same in both themes via tokens */
.pill-8-core{
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: var(--bg);
  box-shadow: 0 2px 10px var(--shadow), 0 0 0 1px color-mix(in srgb, var(--fg) 10%, transparent);
  display: flex;
  align-items: center;
  justify-content: center;
}

.pill-8-dot{
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--muted);
  transition: background 160ms ease, transform 90ms ease;
  transform: scale(calc(1 + var(--lvl) * 0.55));
}

/* progress ring: track + level arc, used for listening level AND
   as an indeterminate-feeling breathing ring in transcribing/transforming */
.pill-8-ring{
  position: absolute;
  inset: 0;
  transform: rotate(-90deg);
}
.pill-8-ring-track{
  fill: none;
  stroke: color-mix(in srgb, var(--fg) 12%, transparent);
  stroke-width: 1.6;
}
.pill-8-ring-level{
  fill: none;
  stroke: var(--accent);
  stroke-width: 1.8;
  stroke-linecap: round;
  --circ: 72.25; /* 2*pi*11.5 */
  stroke-dasharray: var(--circ);
  stroke-dashoffset: calc(var(--circ) * (1 - var(--lvl)));
  opacity: 0;
  transition: stroke-dashoffset 60ms linear;
}

.pill-8-spinner{
  position: absolute;
  inset: 0;
  opacity: 0;
  animation: pill8-spin 900ms linear infinite;
}
.pill-8-spinner circle{
  fill: none;
  stroke: var(--accent);
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-dasharray: 40 20;
}
@keyframes pill8-spin{ to{ transform: rotate(360deg); } }

.pill-8-glyph{
  position: absolute;
  color: var(--fg);
  opacity: 0;
  transform: scale(.6);
  transition: opacity 140ms ease, transform 140ms cubic-bezier(.2,.8,.3,1.3);
}
.pill-8-glyph-ok{ color: var(--ok); }
.pill-8-glyph-err{ color: var(--err); }

/* ---- state: idle-appear / listening ---- */
.pill-8[data-state="listening"] .pill-8-ring-level{ opacity: 1; }
.pill-8[data-state="listening"] .pill-8-dot{ background: var(--accent); }

/* ---- state: transcribing / transforming ---- */
.pill-8[data-state="transcribing"] .pill-8-spinner,
.pill-8[data-state="transforming"] .pill-8-spinner{ opacity: 1; }
.pill-8[data-state="transcribing"] .pill-8-dot,
.pill-8[data-state="transforming"] .pill-8-dot{
  background: var(--accent);
  transform: scale(.85);
  animation: pill8-pulse 1100ms ease-in-out infinite;
}
@keyframes pill8-pulse{
  0%,100%{ opacity: .55; }
  50%{ opacity: 1; }
}
.pill-8[data-state="transforming"] .pill-8-dot{ background: var(--warn); }

/* ---- state: searching ---- */
.pill-8[data-state="searching"] .pill-8-dot{ opacity: 0; }
.pill-8[data-state="searching"] .pill-8-spinner{ opacity: 1; }
.pill-8[data-state="searching"] .pill-8-glyph-search{ opacity: 1; transform: scale(1); }

/* ---- state: done ---- */
.pill-8[data-state="done"] .pill-8-dot{ opacity: 0; }
.pill-8[data-state="done"] .pill-8-core{ box-shadow: 0 2px 10px var(--shadow), 0 0 0 1px color-mix(in srgb, var(--ok) 45%, transparent); }
.pill-8[data-state="done"] .pill-8-glyph-ok{ opacity: 1; transform: scale(1); }

/* ---- state: failed ---- */
.pill-8[data-state="failed"] .pill-8-dot{ opacity: 0; }
.pill-8[data-state="failed"] .pill-8-core{ box-shadow: 0 2px 10px var(--shadow), 0 0 0 1px color-mix(in srgb, var(--err) 50%, transparent); }
.pill-8[data-state="failed"] .pill-8-glyph-err{ opacity: 1; transform: scale(1); }

/* ---- the expanding card, anchored at the dot's right edge ---- */
.pill-8-card{
  position: absolute;
  left: 14px;
  top: 50%;
  transform: translateY(-50%);
  height: 28px;
  width: 0;
  max-width: 232px; /* 28 anchor + up to 232 card ~= 260 total */
  overflow: hidden;
  border-radius: 14px;
  background: var(--bg);
  box-shadow: 0 6px 20px var(--shadow), 0 0 0 1px color-mix(in srgb, var(--fg) 10%, transparent);
  display: flex;
  align-items: stretch;
  transition: width 260ms cubic-bezier(.2,.85,.3,1.15), height 220ms cubic-bezier(.2,.85,.3,1.15), border-radius 220ms ease;
  z-index: 1;
}
.pill-8-card-inner{
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 1px;
  padding: 4px 8px 4px 20px;
}
.pill-8-card-title{
  font-size: 10px;
  font-weight: 600;
  letter-spacing: .02em;
  text-transform: uppercase;
  color: var(--muted);
  white-space: nowrap;
}
.pill-8-card-title::before{ content: "Result"; }
.pill-8-card-body{
  font-size: 12.5px;
  color: var(--fg);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.pill-8-dismiss{
  flex: 0 0 auto;
  width: 26px;
  align-self: stretch;
  display: flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: none;
  color: var(--muted);
  cursor: pointer;
  opacity: 0;
  transition: opacity 120ms ease, color 120ms ease;
}
.pill-8-card:hover .pill-8-dismiss{ opacity: 1; }
.pill-8-dismiss:hover{ color: var(--fg); }

/* card only opens for done / searching(with a query echo) / failed */
.pill-8[data-state="done"] .pill-8-card,
.pill-8[data-state="failed"] .pill-8-card,
.pill-8[data-state="searching"] .pill-8-card{
  width: 220px;
  height: 40px;
  border-radius: 16px;
}
.pill-8[data-state="done"] .pill-8-card-title::before{ content: "Transcribed"; }
.pill-8[data-state="failed"] .pill-8-card-title::before{ content: "Failed"; }
.pill-8[data-state="failed"] .pill-8-card-body{ color: var(--err); }
.pill-8[data-state="searching"] .pill-8-card-title::before{ content: "上網查下…"; }
.pill-8[data-state="searching"] .pill-8-card-body{ color: var(--muted); }

/* idle-appear: bare dot, nothing else */
.pill-8[data-state="idle-appear"] .pill-8-dot{ background: var(--muted); transform: scale(.7); }

/* cancel/hide */
.pill-8[data-state="hidden"]{
  animation: pill8-hide 160ms ease forwards;
  pointer-events: none;
}
@keyframes pill8-hide{
  from{ transform: scale(1); opacity: 1; }
  to{ transform: scale(.5); opacity: 0; }
}

@media (prefers-reduced-motion: reduce){
  .pill-8, .pill-8-card, .pill-8-dot, .pill-8-glyph{ animation: none !important; transition-duration: 1ms !important; }
  .pill-8-spinner{ animation: none !important; opacity: 0 !important; }
  .pill-8[data-state="transcribing"] .pill-8-ring-level,
  .pill-8[data-state="transforming"] .pill-8-ring-level{ opacity: 1; stroke-dashoffset: 0; }
}

js:
function pill8_tick(level, state){
  var els = document.querySelectorAll('.pill-8');
  for (var i = 0; i < els.length; i++){
    var el = els[i];
    var clamped = Math.max(0, Math.min(1, level || 0));
    el.style.setProperty('--level', clamped);
    if (state && el.getAttribute('data-state') !== state){
      el.setAttribute('data-state', state);
    }
  }
}

css:
.pill-9 {
  --p9-level: 0;
  --p9-line: color-mix(in srgb, var(--fg) 12%, transparent);
  --p9-ink: var(--accent);
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: 10px;
  width: 252px;
  height: 56px;
  padding: 0 12px;
  border-radius: 18px;
  background: color-mix(in srgb, var(--bg) 92%, transparent);
  border: 1px solid var(--p9-line);
  box-shadow: 0 10px 30px var(--shadow), 0 1px 0 color-mix(in srgb, var(--fg) 6%, transparent) inset;
  color: var(--fg);
  font: 13px/1.35 -apple-system, BlinkMacSystemFont, "SF Pro Text", "PingFang HK", system-ui, sans-serif;
  -webkit-backdrop-filter: blur(18px) saturate(1.6);
  backdrop-filter: blur(18px) saturate(1.6);
  overflow: hidden;
  transform-origin: 50% 100%;
  animation: p9-appear 240ms cubic-bezier(.2, .9, .25, 1.05) both;
  transition: width 260ms cubic-bezier(.2, .8, .25, 1), height 260ms cubic-bezier(.2, .8, .25, 1),
              border-color 200ms linear, opacity 160ms linear, transform 160ms ease;
}
.pill-9 * { box-sizing: border-box; }

@keyframes p9-appear {
  from { opacity: 0; transform: translateY(10px) scale(.94); }
  to   { opacity: 1; transform: none; }
}

/* ---------- token ---------- */
.p9-token { position: relative; flex: 0 0 auto; width: 26px; height: 26px; perspective: 320px; }
.p9-card {
  position: absolute; inset: 0;
  transform-style: preserve-3d;
  transition: transform 260ms cubic-bezier(.5, 0, .2, 1.2);
}
.p9-face {
  position: absolute; inset: 0;
  display: flex; align-items: center; justify-content: center;
  border-radius: 9px;
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
  background: color-mix(in srgb, var(--p9-ink) 16%, transparent);
  border: 1px solid color-mix(in srgb, var(--p9-ink) 42%, transparent);
  color: var(--p9-ink);
  font-weight: 620;
  letter-spacing: .02em;
}
.p9-back { transform: rotateY(180deg); }
.p9-front .p9-zh, .p9-front .p9-en, .p9-front .p9-neutral { position: absolute; opacity: 0; transition: opacity 120ms linear; }
.p9-front .p9-zh { font-size: 15px; }
.p9-front .p9-en { font-size: 10px; letter-spacing: .06em; }
.p9-front .p9-neutral { font-size: 14px; color: var(--muted); }
.pill-9[data-lang="neutral"] .p9-neutral,
.pill-9[data-lang="zh"] .p9-zh,
.pill-9[data-lang="en"] .p9-en { opacity: 1; }
.pill-9[data-lang="en"] .p9-card { transform: rotateY(360deg); }

.p9-back > * { position: absolute; opacity: 0; transition: opacity 120ms linear; }
.p9-work { font-size: 14px; }
.p9-ok, .p9-bad { font-size: 15px; font-weight: 700; }
.p9-globe { width: 17px; height: 17px; }

.p9-halo {
  position: absolute; inset: -3px;
  border-radius: 12px;
  border: 1.5px solid color-mix(in srgb, var(--p9-ink) 55%, transparent);
  opacity: calc(.12 + var(--p9-level) * .72);
  transform: scale(calc(1 + var(--p9-level) * .16));
  transition: opacity 90ms linear, transform 90ms linear;
  pointer-events: none;
}

/* ---------- stage ---------- */
.p9-stage { position: relative; flex: 1 1 auto; min-width: 0; height: 42px; display: flex; align-items: center; }
.p9-arc { display: block; width: 100%; height: 42px; overflow: visible; }
.p9-arc path { fill: none; stroke-linecap: round; vector-effect: non-scaling-stroke; }
.p9-line   { stroke: var(--p9-ink); stroke-width: 2; }
.p9-trail  { stroke: color-mix(in srgb, var(--p9-ink) 34%, transparent); stroke-width: 2; }
.p9-shuttle { stroke: var(--p9-ink); stroke-width: 2.4; opacity: 0; stroke-dasharray: 26 400; }

.p9-rail {
  position: absolute; left: 0; right: 0; bottom: 4px; height: 2px;
  border-radius: 2px; background: var(--ok);
  transform: scaleX(0); transform-origin: 0 50%; opacity: 0;
  transition: transform 220ms cubic-bezier(.2, .8, .25, 1), opacity 140ms linear;
}
.p9-text {
  position: absolute; left: 0; right: 0; top: 2px;
  display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2;
  overflow: hidden;
  font-size: 12.5px; line-height: 1.32; color: var(--fg);
  opacity: 0; transform: translateY(3px);
  transition: opacity 160ms linear, transform 200ms cubic-bezier(.2, .8, .25, 1);
  pointer-events: none;
}
.p9-hint {
  flex: 0 0 auto; font-size: 11px; color: var(--muted);
  opacity: .8; transition: opacity 140ms linear;
}

/* ---------- states ---------- */
.pill-9[data-state="idle"] .p9-line,
.pill-9[data-state="idle"] .p9-trail { stroke: var(--muted); }
.pill-9[data-state="idle"] .p9-halo { opacity: .1; }

.pill-9[data-state="listening"] .p9-hint { opacity: .5; }

.pill-9[data-state="transcribing"] { --p9-ink: var(--accent); }
.pill-9[data-state="transcribing"] .p9-line,
.pill-9[data-state="transcribing"] .p9-trail { stroke: color-mix(in srgb, var(--fg) 22%, transparent); stroke-width: 1.5; }
.pill-9[data-state="transcribing"] .p9-shuttle { opacity: 1; animation: p9-shuttle 900ms linear infinite; }
@keyframes p9-shuttle { from { stroke-dashoffset: 26; } to { stroke-dashoffset: -200; } }

.pill-9[data-state="transforming"] { --p9-ink: var(--warn); }
.pill-9[data-state="transforming"] .p9-card { transform: rotateY(180deg); }
.pill-9[data-state="transforming"] .p9-work { opacity: 1; animation: p9-spin 1.6s linear infinite; }
.pill-9[data-state="transforming"] .p9-line,
.pill-9[data-state="transforming"] .p9-trail { stroke: color-mix(in srgb, var(--warn) 55%, transparent); stroke-width: 1.5; }
.pill-9[data-state="transforming"] .p9-shuttle { opacity: .9; stroke-dasharray: 14 60; animation: p9-shuttle 1.4s linear infinite reverse; }
@keyframes p9-spin { to { transform: rotate(360deg); } }

.pill-9[data-state="searching"] .p9-card { transform: rotateY(180deg); }
.pill-9[data-state="searching"] .p9-globe { opacity: 1; }
.pill-9[data-state="searching"] .p9-line,
.pill-9[data-state="searching"] .p9-trail { stroke: color-mix(in srgb, var(--fg) 20%, transparent); stroke-width: 1.5; }
.pill-9[data-state="searching"] .p9-shuttle { opacity: 1; stroke-dasharray: 40 400; animation: p9-shuttle 1.15s cubic-bezier(.5, 0, .5, 1) infinite; }

.pill-9[data-state="done"],
.pill-9[data-state="failed"] { width: 340px; height: 74px; align-items: flex-start; padding-top: 12px; }
.pill-9[data-state="done"] .p9-card,
.pill-9[data-state="failed"] .p9-card { transform: rotateY(180deg); }
.pill-9[data-state="done"] .p9-ok { opacity: 1; }
.pill-9[data-state="failed"] .p9-bad { opacity: 1; }
.pill-9[data-state="done"] { --p9-ink: var(--ok); }
.pill-9[data-state="failed"] { --p9-ink: var(--err); border-color: color-mix(in srgb, var(--err) 45%, transparent); animation: p9-nudge 300ms cubic-bezier(.36, .07, .19, .97) both; }
@keyframes p9-nudge { 0%,100% { transform: none; } 30% { transform: translateX(-4px); } 65% { transform: translateX(3px); } }
.pill-9[data-state="done"] .p9-arc,
.pill-9[data-state="failed"] .p9-arc { opacity: 0; }
.pill-9[data-state="done"] .p9-text,
.pill-9[data-state="failed"] .p9-text { opacity: 1; transform: none; }
.pill-9[data-state="failed"] .p9-text { color: var(--err); }
.pill-9[data-state="done"] .p9-rail,
.pill-9[data-state="failed"] .p9-rail { opacity: 1; transform: scaleX(1); }
.pill-9[data-state="failed"] .p9-rail { background: var(--err); }
.pill-9[data-state="done"] .p9-hint,
.pill-9[data-state="failed"] .p9-hint { opacity: 0; }

.pill-9[data-state="hidden"] {
  opacity: 0;
  transform: translateY(8px) scale(.94);
  pointer-events: none;
}

/* ---------- reduced motion ---------- */
@media (prefers-reduced-motion: reduce) {
  .pill-9,
  .pill-9 .p9-card,
  .pill-9 .p9-halo,
  .pill-9 .p9-text,
  .pill-9 .p9-rail { animation: none !important; transition: opacity 120ms linear, width 120ms linear, height 120ms linear; }
  .pill-9 .p9-card { transition: none; }
  .pill-9[data-lang="en"] .p9-card { transform: none; }
  .pill-9[data-lang="en"] .p9-en { opacity: 1; }
  .pill-9[data-state="transforming"] .p9-card,
  .pill-9[data-state="searching"] .p9-card,
  .pill-9[data-state="done"] .p9-card,
  .pill-9[data-state="failed"] .p9-card { transform: none; }
  .pill-9[data-state="transforming"] .p9-front > *,
  .pill-9[data-state="searching"] .p9-front > *,
  .pill-9[data-state="done"] .p9-front > *,
  .pill-9[data-state="failed"] .p9-front > * { opacity: 0; }
  .pill-9 .p9-back { transform: none; backface-visibility: visible; -webkit-backface-visibility: visible; opacity: 0; }
  .pill-9[data-state="transforming"] .p9-back,
  .pill-9[data-state="searching"] .p9-back,
  .pill-9[data-state="done"] .p9-back,
  .pill-9[data-state="failed"] .p9-back { opacity: 1; }
  .pill-9 .p9-work { animation: none !important; }
  .pill-9 .p9-shuttle { animation: none !important; opacity: 0 !important; }
  .pill-9 .p9-halo { transition: opacity 200ms linear; transform: none; }
  .pill-9[data-state="transcribing"] .p9-line,
  .pill-9[data-state="transforming"] .p9-line,
  .pill-9[data-state="searching"] .p9-line { stroke-dasharray: 3 5; }
}

