(function () {
  var W = 168, MID = 21, N = 12, TAU = Math.PI * 2;
  var el, arc, trail, glyph, amp = 0, phase = 0, lastD = "", reduced = false;

  try { reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches; } catch (e) {}

  function bind() {
    if (el && el.isConnected) return true;
    el = document.querySelector(".pill-9");
    if (!el) return false;
    arc = el.querySelector(".p9-line");
    trail = el.querySelector(".p9-trail");
    glyph = el.querySelector(".p9-token");
    return true;
  }

  // Smooth tapered wave: quadratic-midpoint spline over N+1 samples,
  // squared-sine envelope so the stroke always resolves to the baseline.
  function path(a, ph, k) {
    var pts = [], i, x, y, env;
    for (i = 0; i <= N; i++) {
      x = i * W / N;
      env = Math.sin(Math.PI * i / N);
      env = env * env;
      y = MID - Math.sin(ph + i * k) * a * env * 15;
      pts.push(x, y);
    }
    var d = "M" + pts[0].toFixed(1) + " " + pts[1].toFixed(1), mx, my;
    for (i = 1; i < N; i++) {
      mx = (pts[i * 2] + pts[i * 2 + 2]) / 2;
      my = (pts[i * 2 + 1] + pts[i * 2 + 3]) / 2;
      d += "Q" + pts[i * 2].toFixed(1) + " " + pts[i * 2 + 1].toFixed(1) + " " + mx.toFixed(1) + " " + my.toFixed(1);
    }
    return d + "L" + W + " " + MID;
  }

  // Host calls this when the recognizer's language posterior crosses threshold.
  window.pill9_setLang = function (lang) {
    if (!bind()) return;
    if (el.getAttribute("data-lang") !== lang) el.setAttribute("data-lang", lang);
  };

  // Host calls this at 30 Hz. level 0..1, state one of:
  // idle | listening | transcribing | transforming | searching | done | failed | hidden
  window.pill9_tick = function (level, state) {
    if (!bind()) return;
    if (state && el.getAttribute("data-state") !== state) {
      el.setAttribute("data-state", state);
      phase = 0;
    }
    var s = el.getAttribute("data-state");
    var live = (s === "listening");
    var target = live ? Math.max(0, Math.min(1, level || 0))
      : (s === "transcribing" || s === "transforming" || s === "searching" ? 0.12 : 0);
    amp += (target - amp) * (reduced ? 0.12 : 0.35);
    el.style.setProperty("--p9-level", amp.toFixed(3));

    if (s === "done" || s === "failed" || s === "hidden") return;

    if (reduced) {
      var d0 = path(amp * 0.55, Math.PI / 2, 0);
      if (d0 !== lastD) { lastD = d0; arc.setAttribute("d", d0); if (trail) trail.setAttribute("d", d0); }
      return;
    }

    phase += 0.20 + amp * 0.22;           // louder speech drifts faster
    if (phase > TAU * 64) phase -= TAU * 64;
    var d = path(amp, phase, 0.78);
    if (d !== lastD) {                     // skip DOM writes during silence
      lastD = d;
      arc.setAttribute("d", d);
      if (trail) trail.setAttribute("d", path(amp * 0.72, phase - 0.42, 0.78));
    }
  };
})();

css:
.pill-10{
  --p10-h:56px; --p10-w:232px;
  --p10-hair:color-mix(in srgb, var(--fg) 14%, transparent);
  --p10-fill:color-mix(in srgb, var(--fg) 8%, transparent);
  --p10-dim:color-mix(in srgb, var(--fg) 34%, transparent);
  position:relative; width:var(--p10-w); box-sizing:border-box;
  color:var(--fg); text-align:left;
  font:13px/1.35 -apple-system,BlinkMacSystemFont,"SF Pro Text",system-ui,"PingFang HK",sans-serif;
  -webkit-font-smoothing:antialiased;
  transition:width .34s cubic-bezier(.22,1,.36,1);
  animation:p10-appear .26s cubic-bezier(.22,1,.36,1) both;
}
.pill-10[data-cmd="search"],.pill-10[data-cmd="transform"],
.pill-10[data-state="searching"],.pill-10[data-state="done"],.pill-10[data-state="failed"]{--p10-w:260px}
.pill-10[data-state="hidden"]{animation:p10-hide .18s ease-in both}

@keyframes p10-appear{from{opacity:0;transform:translateY(10px) scale(.94)}to{opacity:1;transform:none}}
@keyframes p10-hide{to{opacity:0;transform:translateY(6px) scale(.96)}}
@keyframes p10-chop{0%{transform:scaleX(1) scaleY(1)}38%{transform:scaleX(1.035) scaleY(.9)}70%{transform:scaleX(.99) scaleY(1.03)}100%{transform:none}}
@keyframes p10-spin{to{transform:rotate(360deg)}}
@keyframes p10-blink{0%,45%{opacity:1}55%,100%{opacity:0}}
@keyframes p10-shim{to{background-position:200% 0}}

/* ---- rail ---- */
.pill-10 .p10-shell{
  position:relative; display:flex; align-items:center; height:var(--p10-h);
  padding:0 10px 0 12px; border-radius:16px; overflow:hidden;
  background:var(--bg); box-shadow:var(--shadow);
  border:.5px solid var(--p10-hair);
  transform-origin:50% 50%;
}
.pill-10[data-cmd="search"] .p10-shell,
.pill-10[data-cmd="transform"] .p10-shell{animation:p10-chop .14s cubic-bezier(.3,1.4,.5,1) both}

/* ---- command chip ---- */
.pill-10 .p10-cmd{
  display:flex; align-items:center; gap:5px; flex:none; overflow:hidden;
  max-width:0; padding-right:0; opacity:0; transform:translateX(-8px);
  color:var(--accent); font-weight:600; letter-spacing:.01em; white-space:nowrap;
  transition:max-width .3s cubic-bezier(.22,1,.36,1),padding-right .3s cubic-bezier(.22,1,.36,1),opacity .2s ease,transform .3s cubic-bezier(.22,1,.36,1);
}
.pill-10[data-cmd="search"] .p10-cmd,.pill-10[data-cmd="transform"] .p10-cmd{max-width:106px;padding-right:9px;opacity:1;transform:none}
.pill-10[data-cmd="transform"] .p10-cmd{color:var(--warn)}
.pill-10 .p10-icon{display:flex}
.pill-10 .p10-i{display:none}
.pill-10[data-cmd="search"] .p10-i-globe{display:block}
.pill-10[data-cmd="transform"] .p10-i-wand{display:block}
.pill-10 .p10-cmdlabel{font-size:12px}

/* ---- seam ---- */
.pill-10 .p10-seam{
  flex:none; width:1px; height:24px; margin-right:9px; background:var(--p10-hair);
  transform:scaleY(0); transform-origin:50% 50%; opacity:0;
  transition:transform .26s cubic-bezier(.22,1,.36,1),opacity .2s ease;
}
.pill-10[data-cmd="search"] .p10-seam,.pill-10[data-cmd="transform"] .p10-seam{transform:scaleY(1);opacity:1}

/* ---- payload ---- */
.pill-10 .p10-pay{position:relative;flex:1 1 auto;min-width:0;height:30px;display:flex;align-items:center}
.pill-10 .p10-meter{display:flex;align-items:center;gap:3px;height:26px;transition:opacity .18s ease}
.pill-10 .p10-bar{
  display:block;width:3px;height:26px;border-radius:2px;background:var(--accent);
  transform:scaleY(.1);transform-origin:50% 50%;will-change:transform;
}
.pill-10 .p10-bar:nth-child(1){opacity:.34}
.pill-10 .p10-bar:nth-child(2){opacity:.46}
.pill-10 .p10-bar:nth-child(3){opacity:.6}
.pill-10 .p10-bar:nth-child(4){opacity:.72}
.pill-10 .p10-bar:nth-child(5){opacity:.84}
.pill-10 .p10-bar:nth-child(6){opacity:.93}

.pill-10 .p10-text{
  position:absolute;inset:0;display:flex;align-items:center;gap:2px;
  opacity:0;transform:translateY(4px);pointer-events:none;
  transition:opacity .18s ease,transform .24s cubic-bezier(.22,1,.36,1);
}
.pill-10 .p10-textin{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--fg)}
.pill-10 .p10-caret{flex:none;width:1.5px;height:15px;background:var(--accent);animation:p10-blink 1.05s steps(1,end) infinite}

.pill-10[data-state="transcribing"] .p10-meter,
.pill-10[data-state="transforming"] .p10-meter,
.pill-10[data-state="searching"] .p10-meter,
.pill-10[data-state="done"] .p10-meter,
.pill-10[data-state="failed"] .p10-meter{opacity:0}
.pill-10[data-state="transcribing"] .p10-text,
.pill-10[data-state="transforming"] .p10-text,
.pill-10[data-state="searching"] .p10-text,
.pill-10[data-state="done"] .p10-text,
.pill-10[data-state="failed"] .p10-text{opacity:1;transform:none}
.pill-10[data-state="done"] .p10-caret,.pill-10[data-state="failed"] .p10-caret{display:none}
.pill-10[data-state="failed"] .p10-textin{color:var(--err)}

/* level underline */
.pill-10 .p10-scanwrap{position:absolute;left:0;right:0;bottom:-3px;height:2px;border-radius:2px;background:var(--p10-fill);overflow:hidden;opacity:0;transition:opacity .2s ease}
.pill-10[data-state="listening"] .p10-scanwrap{opacity:1}
.pill-10 .p10-scan{height:100%;background:var(--accent);transform:scaleX(0);transform-origin:0 50%;border-radius:2px;will-change:transform}

/* ---- badge ---- */
.pill-10 .p10-badge{flex:none;width:22px;height:22px;margin-left:8px;position:relative;opacity:0;transform:scale(.7);transition:opacity .18s ease,transform .24s cubic-bezier(.3,1.5,.5,1)}
.pill-10 .p10-b{position:absolute;inset:0;margin:auto;display:none}
.pill-10[data-state="transcribing"] .p10-badge,
.pill-10[data-state="transforming"] .p10-badge,
.pill-10[data-state="searching"] .p10-badge,
.pill-10[data-state="done"] .p10-badge,
.pill-10[data-state="failed"] .p10-badge{opacity:1;transform:none}
.pill-10[data-state="transcribing"] .p10-b-ring,
.pill-10[data-state="transforming"] .p10-b-ring,
.pill-10[data-state="searching"] .p10-b-ring{display:block;color:var(--accent);animation:p10-spin .9s linear infinite;transform-origin:50% 50%}
.pill-10[data-state="transforming"] .p10-b-ring{color:var(--warn)}
.pill-10 .p10-track{opacity:.22}
.pill-10[data-state="done"] .p10-b-ok{display:block;color:var(--ok)}
.pill-10[data-state="failed"] .p10-b-err{display:block;color:var(--err)}

/* ---- result card ---- */
.pill-10 .p10-card{
  margin-top:8px;border-radius:14px;background:var(--bg);box-shadow:var(--shadow);
  border:.5px solid var(--p10-hair);
  display:grid;grid-template-rows:0fr;opacity:0;transform:translateY(-8px) scale(.97);
  transform-origin:50% 0;pointer-events:none;
  transition:grid-template-rows .32s cubic-bezier(.22,1,.36,1),opacity .22s ease,transform .32s cubic-bezier(.22,1,.36,1);
}
.pill-10[data-state="searching"] .p10-card,
.pill-10[data-state="done"][data-cmd="search"] .p10-card,
.pill-10[data-state="failed"][data-cmd="search"] .p10-card{grid-template-rows:1fr;opacity:1;transform:none;pointer-events:auto}
.pill-10 .p10-cardin{overflow:hidden;min-height:0}
.pill-10 .p10-pad{padding:8px}
.pill-10 .p10-skel,.pill-10 .p10-real,.pill-10 .p10-fail{display:none}
.pill-10[data-state="searching"] .p10-skel{display:block}
.pill-10[data-state="done"] .p10-real{display:block}
.pill-10[data-state="failed"] .p10-fail{display:block;padding:6px 6px 8px;color:var(--err);font-size:12px}

.pill-10 .p10-srow{padding:6px}
.pill-10 .p10-sk{display:block;height:9px;border-radius:5px;margin-bottom:6px;
  background:linear-gradient(90deg,var(--p10-fill) 0%,color-mix(in srgb,var(--fg) 18%,transparent) 50%,var(--p10-fill) 100%);
  background-size:200% 100%;animation:p10-shim 1.25s linear infinite}
.pill-10 .p10-row{display:flex;gap:8px;padding:6px;border-radius:9px}
.pill-10 .p10-row+.p10-row{margin-top:2px}
.pill-10 .p10-row:hover{background:var(--p10-fill)}
.pill-10 .p10-rank{flex:none;width:16px;height:16px;margin-top:1px;border-radius:5px;background:var(--p10-fill);color:var(--accent);font-size:10px;font-weight:700;line-height:16px;text-align:center}
.pill-10 .p10-rtext{min-width:0;display:block}
.pill-10 .p10-rtext b{display:block;font-size:12.5px;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.pill-10 .p10-rtext em{display:block;margin-top:1px;font-style:normal;font-size:11px;color:var(--muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}

@media (prefers-reduced-motion:reduce){
  .pill-10,.pill-10 *{animation:none!important}
  .pill-10{transition:width .001s}
  .pill-10 .p10-shell,.pill-10 .p10-card{transition:opacity .12s linear}
  .pill-10 .p10-cmd,.pill-10 .p10-seam,.pill-10 .p10-text,.pill-10 .p10-badge{transition:opacity .12s linear}
  .pill-10 .p10-card{transform:none;grid-template-rows:0fr}
  .pill-10[data-state="searching"] .p10-card,
  .pill-10[data-state="done"][data-cmd="search"] .p10-card,
  .pill-10[data-state="failed"][data-cmd="search"] .p10-card{grid-template-rows:1fr}
  .pill-10 .p10-caret{opacity:1}
  .pill-10 .p10-sk{background:var(--p10-fill)}
  .pill-10 .p10-bar{transition:none}
}

