(function(){
  var root, bars, scan, hist, N, redu, cur = "", lastScan = -1;
  function init(){
    root = document.querySelector(".pill-10");
    if(!root) return false;
    bars = root.querySelectorAll(".p10-bar");
    scan = root.querySelector(".p10-scan");
    N = bars.length; hist = new Array(N).fill(0);
    redu = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    cur = root.getAttribute("data-state") || "";
    return true;
  }
  window.pill10_tick = function(level, state){
    if(!root && !init()) return;
    if(state && state !== cur){ cur = state; root.setAttribute("data-state", state); }
    var v = level; if(!(v >= 0)) v = 0; if(v > 1) v = 1;

    // scrolling scope: newest sample enters at the right, older ones travel left
    if(redu){ for(var k=0;k<N;k++) hist[k] = v * 0.55; }
    else { for(var i=0;i<N-1;i++) hist[i] = hist[i+1]; hist[N-1] = v; }

    var live = (cur === "listening");
    for(var b=0;b<N;b++){
      var s = live ? 0.10 + 0.90 * Math.pow(hist[b], 0.75) : 0.10;
      bars[b].style.transform = "scaleY(" + s.toFixed(3) + ")";
    }
    var w = live ? v : 0;
    if(Math.abs(w - lastScan) > 0.01){ lastScan = w; scan.style.transform = "scaleX(" + w.toFixed(3) + ")"; }
  };
  // host may also set the detected command: "none" | "search" | "transform"
  window.pill10_command = function(cmd){
    if(!root && !init()) return;
    root.setAttribute("data-cmd", cmd || "none");
  };
})();
